ST.xhtml:
(* ---- 手动/停用：积分清零、指令归零（防积分残留） ---- *)
IF NOT auto_mode THEN
    integ := 0.0;
    mv := 0;
ELSE
    (* ---- PI 位置式：Kp=5, Ki=0.2（零点对消对象极点），采样=任务周期 T#20MS ---- *)
    err := INT_TO_REAL(sp - pv);
    mv_r := 5.0 * err + integ;
    (* 条件积分抗饱和：输出饱和且误差继续同向时暂停积分，防退出饱和后超调 *)
    IF NOT (mv_r > 100.0 AND err > 0.0) AND NOT (mv_r < 0.0 AND err < 0.0) THEN
        integ := integ + 0.2 * err * 0.02;
    END_IF;
    IF integ > 100.0 THEN integ := 100.0; END_IF;
    IF integ < 0.0 THEN integ := 0.0; END_IF;
    mv_r := 5.0 * err + integ;
    IF mv_r > 100.0 THEN mv_r := 100.0; END_IF;
    IF mv_r < 0.0 THEN mv_r := 0.0; END_IF;
    mv := REAL_TO_INT(mv_r);
END_IF;

(* ---- 偏差报警（量程 20%） ---- *)
dev_alarm := auto_mode AND (ABS(sp - pv) > 20);
